import {z} from 'zod';
import {zodResponseFormat} from 'openai/helpers/zod';
import {MarketingReportSchema,ChecklistItemSchema} from './reportSchema';

// Only fields generated by the model belong here. Collection evidence, account
// state and optional server-side enrichments are attached after validation.
const report=MarketingReportSchema.shape;
export const MarketingModelReportSchema=z.object({
  url:report.url,overallScore:report.overallScore,oneLineSummary:report.oneLineSummary,
  diagnosis:report.diagnosis,
  checklist:z.array(ChecklistItemSchema.pick({id:true,category:true,label:true,status:true,currentValue:true,diagnosis:true,guide:true})).length(12),
  criticalIssues:z.array(report.criticalIssues.element.pick({title:true,problem:true,reason:true,recommendation:true,priority:true,badExample:true,goodExample:true,exampleNote:true}).required()).max(4),
  quickWinsDetailed:z.array(report.quickWinsDetailed.unwrap().element.pick({title:true,steps:true,beforeExample:true,afterExample:true}).required()).max(3),
  priorityRoadmap:report.priorityRoadmap,
  exampleCopy:report.exampleCopy.pick({currentHeroHeadline:true,currentCtaText:true,heroHeadline:true,subHeadline:true,ctaText:true}).required(),
  finalCta:report.finalCta,
});
export const MARKETING_RESPONSE_FORMAT=zodResponseFormat(MarketingModelReportSchema,'marketing_report');
